import java.util.*;
import java.lang.*;
import java.io.*;

public class Ideone {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String a = sc.next();

        boolean inside = false;
        int best = 0;
        int words = 0;
        int len = 0;
        int i = 0;

        while (i < n) {
            char c = a.charAt(i);
            switch (c) {
                case '_':
                    if (inside && len != 0) {
                        words++;
                    } else {
                        if (len > best) best = len;
                    }
                    len = 0;
                    break;
                case '(':
                    inside = true;
                    if (len > best) best = len;
                    len = 0;
                    break;
                case ')':
                    inside = false;
                    if (len > 0) {
                        words++;
                    }
                    len = 0;
                    break;
                default:
                    len++;
            }
            i++;
        }

        if (len > best) best = len;
        System.out.println(best + " " + words);
    }
}
